// V7: the coordination claims of docs/COORDINATION_GRAPH.md, README.md and
// docs/PCA_METHODOLOGY.md match the code. The doc's tables are generated by
// scripts/coordination_matrix.mjs from the store actions and the useF1Store
// selectors; the Timing Sheet's lap-range bar writes the shared brushed range
// (lapBrushUpdate), so Position by Lap <-> Timing Sheet is linked both ways.
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  coordinationOf, renderMarkdown, blockOf, scanSource, readStore, DOC,
} from '../../scripts/coordination_matrix.mjs';
import { lapBrushUpdate } from '../utils/views/lapTimeChart.js';

const SRC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ROOT = path.resolve(SRC, '../..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const coord = coordinationOf(SRC);
const { views } = coord;
const writes = (v, f) => views[v]?.writes.includes(f) || false;
const reads = (v, f) => views[v]?.reads.includes(f) || false;

describe('V7: the generated coordination tables are the code', () => {
  it('the block in docs/COORDINATION_GRAPH.md equals the script output', () => {
    const block = blockOf(fs.readFileSync(DOC, 'utf8'));
    expect(block, 'markers missing').not.toBeNull();
    // after changing a link: node scripts/coordination_matrix.mjs --write (from frontend/)
    expect(block).toBe(renderMarkdown(coord).trim());
  });

  it('an action only listed in a dependency array is not a write; a call or a handler is', () => {
    const store = readStore('export const useF1Store = create((set, get) => ({\n'
      + '  brushLapRange: null,\n'
      + '  setBrushLapRange: (range) => set({ brushLapRange: range }),\n'
      + '}));\n');
    const listed = 'const setB = useF1Store((s) => s.setBrushLapRange);\nuseEffect(() => {}, [setB]);';
    const called = 'const setB = useF1Store((s) => s.setBrushLapRange);\nconst f = () => setB([1, 2]);';
    const handler = 'const setB = useF1Store((s) => s.setBrushLapRange);\nreturn <Bar onRangeChange={setB} />;';
    expect([...scanSource(listed, store).writes]).toEqual([]);
    expect([...scanSource(called, store).writes]).toEqual(['brushLapRange']);
    expect([...scanSource(handler, store).writes]).toEqual(['brushLapRange']);
  });
});

describe('V7: Position by Lap <-> Timing Sheet through brushLapRange, both ways', () => {
  it('the Timing Sheet bar writes the shared brushed range and the selected range; a click clears both', () => {
    expect(lapBrushUpdate([12, 5])).toEqual({ brushLapRange: [5, 12], selectedLapRange: [5, 12] });
    expect(lapBrushUpdate(null)).toEqual({ brushLapRange: null, selectedLapRange: null });
    const sheet = fs.readFileSync(path.join(SRC, 'components/visualizations/LapTimeChart.jsx'), 'utf8');
    expect(sheet).toMatch(/const next = lapBrushUpdate\(range\);\s*setBrushLapRange\(next\.brushLapRange\);\s*setSelectedLapRange\(next\.selectedLapRange\);/);
  });

  it('both views write brushLapRange and both subscribe to it; Tyre Degradation fits it', () => {
    for (const v of ['LapTimeChart', 'PositionByLap']) {
      expect(writes(v, 'brushLapRange'), `${v} writes`).toBe(true);
      expect(reads(v, 'brushLapRange'), `${v} subscribes`).toBe(true);
    }
    expect(reads('TireDegradation', 'brushLapRange')).toBe(true);
    expect(views.TireDegradation?.writes || []).toEqual([]);
    const both = renderMarkdown(coord).split('\n').find((l) => l.startsWith('| LapTimeChart | PositionByLap |'));
    console.log(`linked both ways: ${both}`);
    expect(both).toMatch(/^\| LapTimeChart \| PositionByLap \| [^|]*`brushLapRange`[^|]*\| [^|]*`brushLapRange`/);
  });
});

describe('V7: a clear or a new brush in either view leaves both on the same range', () => {
  const sheetShows = (s) => s.brushLapRange || s.selectedLapRange;
  it('drag on the Timing Sheet bar, then clear in Position by Lap: both views show no range', async () => {
    const { useF1Store } = await import('../store/useF1Store.js');
    const st = () => useF1Store.getState();
    useF1Store.setState({ brushLapRange: null, selectedLapRange: null });
    const next = lapBrushUpdate([10, 20]);
    st().setBrushLapRange(next.brushLapRange);
    st().setSelectedLapRange(next.selectedLapRange);
    expect(sheetShows(st())).toEqual([10, 20]);
    // Position by Lap: a new brush moves the linked selection with it
    st().setBrushLapRange([12, 15]);
    expect(st().selectedLapRange).toEqual([12, 15]);
    // Position by Lap: the chip X / a click clears the brush and the selection it wrote
    st().setBrushLapRange(null);
    expect(st().brushLapRange).toBeNull();
    expect(sheetShows(st())).toBeNull();
  });

  // V7 r2: a stint's range was kept under selectedLapRange only, so the
  // sheet's title named it while its rows and the brush showed another range
  // or none. The store now keeps one range: the newest action wins everywhere.
  it('one lap range: a stint click sets the range of every view, a brush replaces it, a clear clears it everywhere', async () => {
    const { useF1Store } = await import('../store/useF1Store.js');
    const st = () => useF1Store.getState();
    useF1Store.setState({ brushLapRange: null, selectedLapRange: null });
    // the five readers: sheet bar/title, sheet rows, Position by Lap brush, Strategy Timeline band, Tyre Degradation
    const views = (x) => [sheetShows(x), x.brushLapRange, x.brushLapRange, x.selectedLapRange, x.brushLapRange || x.selectedLapRange];
    st().setSelectedLapRange([5, 8]); // stint click
    expect(new Set(views(st()).map((v) => JSON.stringify(v)))).toEqual(new Set([JSON.stringify([5, 8])]));
    st().setBrushLapRange([12, 15]); // Position by Lap brush
    expect(new Set(views(st()).map((v) => JSON.stringify(v)))).toEqual(new Set([JSON.stringify([12, 15])]));
    st().setBrushLapRange(null); // clear on Position by Lap
    expect(views(st())).toEqual([null, null, null, null, null]);
    st().setSelectedLapRange([20, 24]); // pit window
    st().clearSelection(); // Esc
    expect(views(st())).toEqual([null, null, null, null, null]);
  });
});

describe('V7: the claims removed from the docs are absent from the code', () => {
  const LAP_RANGES = ['selectedLapRange', 'brushLapRange'];

  it('the Track Map and the PCA biplot subscribe to no lap range; Race Analysis writes none', () => {
    for (const f of LAP_RANGES) {
      expect(reads('TrackMap', f), `TrackMap ${f}`).toBe(false);
      expect(reads('PCABiplot', f), `PCABiplot ${f}`).toBe(false);
      expect(writes('StrategyAnalysis', f), `StrategyAnalysis ${f}`).toBe(false);
    }
  });

  it('the lap ranges have exactly the writers and subscribers the doc names', () => {
    const field = (f) => coord.fields.find((x) => x.field === f);
    // Position by Lap through setBrushLapRange: the selection the brush wrote follows the brush (V7)
    expect(field('selectedLapRange').writers).toEqual(['LapTimeChart', 'PCAAnalysisPanel', 'PositionByLap', 'StrategyTimeline', 'TimelinePlayer', 'commandRegistry']);
    expect(field('selectedLapRange').readers).toEqual(['LapTimeChart', 'StrategyTimeline', 'TelemetryStrip', 'TireDegradation']);
    // one range under two names (V7 r2): every lap-range action writes both
    expect(field('brushLapRange').writers).toEqual(field('selectedLapRange').writers);
    expect(field('selectedPCAPoints').readers).toEqual(['PCAAnalysisPanel', 'PCABiplot']);
    expect(field('pcaStrategyAnalysis').readers).toEqual(['PCAAnalysisPanel', 'StrategyAnalysis', 'StrategyTimeline']);
    expect(field('trackProgress').writers).toEqual([]);
  });

  it('no store field, action or doc names a t-SNE selection', () => {
    const store = fs.readFileSync(path.join(SRC, 'store/useF1Store.js'), 'utf8');
    expect(store).not.toMatch(/TSNE|tsne/);
    for (const doc of ['docs/COORDINATION_GRAPH.md', 'README.md', 'docs/PCA_METHODOLOGY.md']) {
      expect(read(doc), doc).not.toMatch(/selectedTSNEPoints|fetchTSNEAnalysis|setSelectedTSNEPoints|TSNEScatterplot/);
    }
  });

  it('README and the PCA methodology no longer say the Track Map or the biplot react to a lap range', () => {
    const readme = read('README.md');
    const pca = read('docs/PCA_METHODOLOGY.md');
    expect(pca).not.toMatch(/`TrackMap`[^.]*dim/);
    expect(pca).not.toMatch(/LapTimeChart`, `TrackMap` and `StrategyTimeline` dim/);
    expect(readme).not.toMatch(/t-SNE\s*│|tsne_features|tsne_compute/);
    // every "A (ViewA) <-> B (ViewB)" bullet of the README names fields the code links both ways
    const bullets = readme.split('\n').filter((l) => /^- \*\*.*\((\w+)\) ↔ .*\((\w+)\):?\*\*/.test(l));
    expect(bullets.length).toBeGreaterThanOrEqual(5);
    for (const b of bullets) {
      const [, a, z] = /\((\w+)\) ↔ .*?\((\w+)\):?\*\*/.exec(b);
      const named = [...b.matchAll(/`(\w+)`/g)].map((m) => m[1]).filter((f) => coord.fields.some((x) => x.field === f));
      expect(named.length, b).toBeGreaterThan(0);
      const ab = views[a].writes.filter((f) => views[z].reads.includes(f));
      const za = views[z].writes.filter((f) => views[a].reads.includes(f));
      for (const f of named) expect(ab.includes(f) || za.includes(f), `${a} <-> ${z}: ${f}`).toBe(true);
      expect(ab.length > 0 && za.length > 0, `${a} <-> ${z} linked both ways`).toBe(true);
    }
  });
});
